    assert bb.hasRemaining();
    int bitCount = 0;
    for (int byteIndex = 0; byteIndex < 4; byteIndex++) {
        byte currentByte = bb.get();
        bitCount += currentByte & 0x3F; // Only grab the lower 6 bits
