import java.io.File;
import java.net.JarURLConnection;
import java.net.URL;
import java.util.Enumeration;
import java.util.List;
import java.util.jar.JarFile;
import java.util.jar.Manifest;

public static void addToClassPath(Vector<URL> cpV, String dir) {
    File dirPath = new File(dir);
    if (!dirPath.exists() || !dirPath.isDirectory()) {
        throw new IllegalArgumentException("Invalid directory: " + dir);
    }

    File[] files = dirPath.listFiles((f) -> f.isFile() && f.getAbsolutePath().endsWith(".jar") && f.getAbsolutePath().toLowerCase().endsWith(".jar"));
    for (File file : files) {
        try {
            URL url = file.toURI().toURL();
            cpV.add(url);
        } catch (Exception e) {
            e.printStackTrace();
            if (!isRuntimeException(e)) {
                if (e instanceof Error) {
                    Throwables.propagateIfPossible((Error) e);
                } else if (e instanceof RuntimeException) {
                    Throwables.propagateIfPossible((RuntimeException) e);
                } else {
                    throw new RuntimeException(e.getMessage());
                }
            }
        }
    }

    try {
        URL classpathResource = ClassLoader.getSystemClassLoader().getResource("/");
        if (classpathResource != null) {
            JarURLConnection jarURLConnection = (JarURLConnection) classpathResource.openConnection();
            Manifest manifest = jarURLConnection.getManifest();
            if (manifest != null) {
                List<String> classNames = manifest.getMainAttributes().getList("Class-Path");
                for (String className : classNames) {
                    URL classPathResource = new URL(classPathResource, className.replaceFirst(":", ""))
                            .toURI().toURL();
                    cpV.add(classPathResource);
                }
            }
        }
    } catch (Exception e) {
        e.printStackTrace();
        if (!isRuntimeException(e)) {
