    if (offset + WRITE_CHUNK_SIZE > b.length) {
      int chunkSize = b.length - offset; // Number of bytes to write in this iteration
      outputStream.write(b, offset, chunkSize); // Write the chunk to the output stream
      remaining -= chunkSize; // Update remaining bytes to write
      offset = 0; // Reset the offset for the next iteration
    } else {
      outputStream.write(b, offset, WRITE_CHUNK_SIZE); // Write the full chunk to the output stream
      remaining -= WRITE_CHUNK_SIZE; // Update remaining bytes to write
      offset += WRITE_CHUNK_SIZE; // Increment the offset for the next iteration
    }
  }
}
