import java.util.ArrayList;
import java.util.List;
import java.util.Iterator;

class TimeRange {
    long startTime;
    long endTime;

    TimeRange(long startTime, long endTime) {
        this.startTime = startTime;
        this.endTime = endTime;
    }
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long fetchDataDuration = 60 * 60 * 1000; // 1 hour in milliseconds
    long duration = end - start;
    int numRanges = (int) Math.ceil(duration / fetchDataDuration);
    long rangeSize = duration / numRanges;

    for (int i = 0; i < numRanges; i++) {
        long rangeStart = start + i * rangeSize;
        long rangeEnd = Math.min(start + (i + 1) * rangeSize, end);
        timeRanges.add(new TimeRange(rangeStart, rangeEnd));
    }

    return timeRanges;
}
