public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Ensuring the dayStep does not exceed the maximum value to avoid overflow
    if (dayStep > Long.MAX_VALUE / 365 / 24 / 60 / 60 * 1000) {
        throw new IllegalArgumentException("dayStep cannot exceed the maximum value");
    }

