public static long compressTimeBucket(long timeBucket, int dayStep) {
    long year = timeBucket / 10000;
    long month = (timeBucket / 10000) % 100;
    long day = timeBucket % 10000;

    // Calculate the new day starting from the first day of the month
    long newDay = day - day % dayStep;
    if (newDay < 1) {
        // If day count becomes negative, wrap around to previous month
        month -= 1;
        if (month < 1) {
            // If month count becomes negative, wrap around to previous year
            year -= 1;
            month += 12;
        }
        day = 31;
    } else {
        day = newDay;
    }

    // Reconstruct the time bucket
    return (year * 10000) + (month * 10000) + day;
}
