public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || len <= 0) {
        return 0;
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        final int c = str.charAt(i);
        if ((c & 0xC0) != 0x80) {
            if ((c & 0xE0) == 0xE0 && i + 2 < str.length() && validSurrogate(c, str.charAt(i + 1))) {
                size += 2;
            } else {
                size += 1;
            }
        } else if ((c & 0xF0) == 0xF0 && i + 3 < str.length() && validSurrogate(c, str.charAt(i + 1)) && validSurrogate(str.charAt(i + 2), str.charAt(i + 3))) {
            size += 3;
        } else if ((c & 0xF8) == 0xF8 && i + 4 < str.length() && validSurrogate(c, str.charAt(i + 1)) && validSurrogate(str.charAt(i + 2)) && validSurrogate(str.charAt(i + 3), str.charAt(i + 4))) {
            size += 4;
        } else {
            if ((c & 0xFC) == 0xFC && i + 5 < str.length() && validSurrogate(c, str.charAt(i + 1)) && validSurrogate(str.charAt(i + 2)) && validSurrogate(str.charAt(i + 3)) && validSurrogate(str.charAt(i + 4))) {
                size += 5;
            } else {
                return 0; // Not a valid UTF-8 sequence
            }
        }
    }

    return size;
}

private static boolean validSurrogate(int c1, int c2) {
    return (c1 | 0xFC) == 0xD800 && (c2 | 0xFC) == 0xDC00;
}
