public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    int i = index;
    while (i < index + len) {
        int b = str.charAt(i);
        if ((b & 0xc0) != 0x80) {
            size++; // single byte character
        } else if ((b & 0xe0) == 0xc0) {
            if (i + 1 >= index + len) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            b = str.charAt(i + 1);
            if ((b & 0xc0) != 0x80) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            size += 2; // two-byte character
        } else if ((b & 0xf0) == 0xe0) {
            if (i + 2 >= index + len) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            b = str.charAt(i + 1);
            if ((b & 0xc0) != 0x80) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            b = str.charAt(i + 2);
            if ((b & 0xc0) != 0x80) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            size += 3; // three-byte character
        } else if ((b & 0xf8) == 0xf0) {
            if (i + 3 >= index + len) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            b = str.charAt(i + 1);
            if ((b & 0xc0) != 0x80) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            b = str.charAt(i + 2);
            if ((b & 0xc0) != 0x80) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            b = str.charAt(i + 3);
            if ((b & 0xc0) != 0x80) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            size += 4; // four-byte character
        }
        i++;
    }
    return size;
