public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int utf8Size = 0;
    if (str == null) {
        return utf8Size;
    }
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c < 128) {
            utf8Size += 1;
        } else if (c >= 192 && c < 224) {
            utf8Size += 2;
        } else if (c >= 224 && c < 240) {
            utf8Size += 3;
        } else if (c >= 240 && c < 248) {
            utf8Size += 4;
        } else if (c >= 248 && c < 252) {
            utf8Size += 5;
        } else if (c >= 252 && c < 255) {
            utf8Size += 6;
        }
    }
    return utf8Size;
}
