        throw new IllegalArgumentException("byteArrayValue is null and byteOffset + byteLength exceeds the length of byteArrayValue.");
    }

    int loc0 = this.length;
    int loc2 = byteOffset;

    while (loc2 < byteOffset + byteLength) {
