    if (next == null) {
        edge.getTail().setNext(null);
    } else {
        next.setPrev(null);
    }

    // Remove the edge from the head's list
    TreeEdge prev = edge.getHead().getPrev();
    if (prev == null) {
        edge.getHead().setPrev(null);
    } else {
        prev.setNext(null);
    }

    // Clear the pointers
    edge.setTail(null);
    edge.setHead(null);
}
