private static boolean tryCompare(final String str, final String suffix) {
    try {
        return str.regionMatches(true, str.length() - suffix.length(), suffix, 0, suffix.length());
    } catch (StringIndexOutOfBoundsException e) {
        // This will only happen if str is shorter than suffix and we compare str to '' after str.endsWith(suffix)
        return false;
    }
