private void pop(final String descriptor) {
    if (descriptor.isEmpty()) {
        return;
    }

    // Check if the descriptor describes an argument type
    if (descriptor.charAt(0) == '(') {
        // Extract the argument count
        int argumentCount = Integer.parseInt(descriptor.substring(1, descriptor.indexOf(')')));
        // Shift the output frame stack accordingly
        for (int i = 0; i < argumentCount; i++) {
            outputFrameStack.pop();
        }
    } else {
        // If the descriptor is a type, directly remove it from the output frame stack
        outputFrameStack.pop();
