public static int nextPrime(int desiredCapacity){
    // Check if the desired capacity is less than or equal to 0
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("desiredCapacity must be greater than 0");
    }

    // If desiredCapacity is exact, find the next number and check if it's prime
    if (desiredCapacity >= 1000) {
        int result = desiredCapacity;
        // Find the next multiple of 11
        result = (result + 10) / 11 * 11;

        // Check for prime
        while (!isPrime(result)) {
            result += 11;
        }

        return result;
    }

    // If desiredCapacity is less than 1000, directly find the next prime
    else {
        int result = desiredCapacity;
        while (!isPrime(result)) {
            result++;
        }

        return result;
    }
}

