public static int primeNear(int n){
    int s = 0; 
    for(int i = 1;i<=n;i++){
        if(n%i == 0){
            s++;
        }
    }
    int primes[] = new int[2*n]; 
    primes[0] = 2; 
    int k = 1; 
    for(int i = 3;i<=n;i++){
        int r = i % s; 
        if(r == 0){
            continue;
        }
        if(checkPrimes(new int[]{primes[k-1],i})){
            primes[k] = i; 
            k++;
        }
    }
    for(int i = 1;i<k;i++){
        if(primes[i] - primes[i-1] < 11){
            return primes[i];
        }
    }
    return -1;
}
