        throw new IllegalArgumentException("Input must be at least 2");
    }
    if (desiredCapacity <= 1000) {
        int threshold = desiredCapacity * 7 / 6; // More accurate approximation than 2 * log(desiredCapacity) + 9
        for (int i = 2; i <= threshold; i++) {
            if (isPrime(i)) {
                return i;
            }
        }
    }
    // For large values, return the next available prime number
