        JsonNode value = entry.getValue();
        if (value.isObject()) {
            content.put(key, buildContent((JsonObject) value));
        } else if (value.isArray()) {
            content.put(key, Arrays.stream(((JsonArray) value).elements())
                    .map(JsonNode::asText)
                    .map(value -> value)
                    .collect(Collectors.toList()));
        } else {
            content.put(key, value.asText());
        }
    }
    return content;
}
