public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder result = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        if (str.charAt(i) == '\\' && i + 1 < str.length()) {
            char nextChar = str.charAt(i + 1);
            if (nextChar == '\\' || nextChar == '\b' || nextChar == '\t' || nextChar == '\n' || nextChar == '\r' || nextChar == '\"' || nextChar == '\'') {
                result.append(nextChar);
                i++;
            } else if (nextChar == 'u') {
                if (i + 6 < str.length()) {
                    try {
                        String unicode = str.substring(i + 2, i + 6);
                        result.append((char) Integer.parseInt(unicode, 16));
                        i += 5;
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid Unicode escape sequence");
                    }
                } else {
                    throw new Exception("Invalid Unicode escape sequence");
                }
            } else {
                throw new Exception("Unsupported escape character");
            }
        } else {
            result.append(str.charAt(i));
        }
    }
    return result.toString();
}
