public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder current = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 < str.length()) {
                char next = str.charAt(i + 1);
                switch (next) {
                    case 'n':
                        current.append('\n');
                        break;
                    case 't':
                        current.append('\t');
                        break;
                    case '\\':
                        current.append('\\');
                        break;
                    case '\'':
                        current.append('\'');
                        break;
                    case '"':
                        current.append("\"");
                        break;
                    default:
                        throw new IllegalArgumentException("Unrecognized escape sequence: \\ " + next);
                }
                i++;
            }
        } else {
            current.append(c);
        }
        if (c == '\n' || c == '\r') {
            result.append(current.toString());
            current.setLength(0);
        }
    }
    result.append(current.toString());
    return result.toString();
}
