    if (offset < 0 || offset >= data.length) {
        throw new IndexOutOfBoundsException("Offset must be within the range of the data array.");
    }

    // Read the two bytes from the data array
    int highByte = data[offset] & 0xFF;
    int lowByte = data[offset + 1] & 0xFF;

    // Combine the high and low bytes to form a 16-bit value
    short value = (short) ((highByte << 8) | lowByte);

    // Return the read value
    return value;
}
