            throw new IllegalArgumentException("properties cannot be null");
        }

        // Create a new ObjectMapper instance
        ObjectMapper mapper = new ObjectMapper();

        // Create a new JsonObject to store the converted properties
        JsonObject result = new JsonObject();

        // Loop through each property
        for (KeyStringValuePair prop : properties) {
            try {
                // Convert the property value to the appropriate JSON data type using ObjectMapper
                Object value = mapper.convertValue(prop.getValue(), Object.class);

                // Set the property in the result JsonObject
                result.addProperty(prop.getKey(), value);
            } catch (IllegalArgumentException e) {
                // Handle any conversion exceptions and log them
                System.err.println("Error converting property: " + prop.getKey() + ". Reason: " + e.getMessage());
            }
        }

        return result;
    }
}
