public final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer) {
    if ( constantPoolEntryIndex < 1 || constantPoolEntryIndex >= classFileBuffer.constantPoolTableSize ) {
        throw new IllegalArgumentException("Invalid constant pool entry index");
    }

    ConstantPoolEntry entry = classFileBuffer.constantPoolTable[constantPoolEntryIndex];
    if ( entry == null || ! entry.isConstantUtf8() ) {
        throw new IllegalArgumentException("Non-UTF8 constant pool entry");
    }

    byte[] value = new byte[entry.getByteLength()];
    entry.set(value);

    int offset = 0;
    while (offset < value.length) {
        int length = value[offset++] & 0xff;
        char[] chars = new char[length];
