private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) throw new IllegalArgumentException("Predicate cannot be null");
    if (start == null || stop == null) throw new IllegalArgumentException("Source and stop nodes cannot be null");

    OuterFaceCirculator circulator = new OuterFaceCirculator(start);
    Node currentNode = circulator.next();

    while (currentNode != null) {
        if (predicate.test(currentNode)) {
            return new OuterFaceCirculator(currentNode);
        }
        currentNode = circulator.next(dir, start, stop);
    }

    if (predicate.test(stop)) {
        return new OuterFaceCirculator(stop);
    }

    return null;
}
