public int compare(Object aObj1,Object aObj2) throws Exception {
    byte[] array1 = (byte[]) aObj1;
    byte[] array2 = (byte[]) aObj2;

    if (array1.length == 0) {
        return -1;
    }

    if (array2.length == 0) {
        return 1;
    }

    int length = Math.min(array1.length, array2.length);
    for (int i = 0; i < length; i++) {
        if (array1[i] < array2[i]) {
            return -1;
        }
        if (array1[i] > array2[i]) {
            return 1;
        }
    }

    if (array1.length < array2.length) {
        return -1;
    } else if (array1.length > array2.length) {
        return 1;
    } else {
        return 0;
    }
}
