public class TSPSolver {
    public GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
        Set<GraphNode> nodes = new HashSet<>();

        for (E edge : tour) {
            V v1 = graph.getV(edge.getStart());
            V v2 = graph.getV(edge.getEnd());

            if (!nodes.contains(new GraphNode(v1, edge))) {
                nodes.add(new GraphNode(v1, edge));
            }

            if (!nodes.contains(new GraphNode(v2, edge))) {
                nodes.add(new GraphNode(v2, edge));
            }
        }

        GraphPath<V, E> path = new GraphPath<>(nodes, graph);

        return path;
    }
}
