public int addConstantNameAndType(final String name, final String descriptor) {
    // Check if the constant pool already contains a similar item
    for (int i = 1; i < constantPoolSize; i++) {
        if (constants[i].getValue().equals(name) && constants[i].getDescriptor().equals(descriptor)) {
            // Return the already existing Sym as the new Sym
            return constants[i].getEntry();
        }
    }
    // If not found, add a new Sym to the constant pool and return its entry
    Sym sym = new Sym(name, descriptor, constantPoolSize++);
    constants[constantPoolSize - 1] = sym;
    return sym.getEntry();
}
