    for (int i = 0; i < input.length(); i++) {
        if (escaping) {
            if (input.charAt(i) == '\\') {
                result.append(input.charAt(i));
            } else {
                result.append('\\').append(input.charAt(i));
            }
            escaping = false;
        } else if (input.charAt(i) == '\\') {
            escaping = true;
        } else if (input.charAt(i) == '.') {
            result.append("\\.");
        } else {
            result.append(input.charAt(i));
        }
    }

    return result.toString();
