private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (minLabel < 0 || minLabel >= labels.size()) {
        throw new IllegalArgumentException("Minimum label must be between 0 and the size of the labels list.");
    }

    List<Set<Integer>> newBucketsByLabel = new ArrayList<>(labels.size());
    for (int i = 0; i < labels.size(); i++) {
        newBucketsByLabel.add(null);
    }

    Iterator<Integer> labelIterator = labels.iterator();
    while (labelIterator.hasNext()) {
        int label = labelIterator.next();
        if (label == minLabel) {
            labelIterator.remove();
        } else {
            Set<Integer> bucket = bucketsByLabel.get(label);
            if (bucket != null) {
                Set<Integer> newBucket = bucketsByLabel.get(0);
                newBucket.addAll(bucket);
                bucketsByLabel.set(label, Set.of());
            }
        }
    }

    int newMinLabel = 0;
    for (int i = 0; i < labels.size(); i++) {
        if (labels.get(i) > newMinLabel && bucketsByLabel.get(i) != null) {
            newMinLabel = labels.get(i);
        }
    }

    bucketsByLabel = newBucketsByLabel;
    labels = Arrays.asList();
    labels.add(newMinLabel);
}
