private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (minLabel >= labels.size() || bucketsByLabel == null) {
        throw new IllegalArgumentException("Invalid input");
    }

    try {
        int lastLabel = labels.get(0);
        while (lastLabel > minLabel) {
            Set<Integer> bucket = bucketsByLabel.get(lastLabel - 1);
            if (bucket.isEmpty()) {
                lastLabel--;
                continue;
            }
            int firstLabel = bucket.stream().findFirst().get();
            bucketsByLabel.set(firstLabel, new HashSet<>());
            labels.set(firstLabel, 0);
            labels.set(lastLabel - 1, lastLabel);
            lastLabel++;
        }
        labels.set(minLabel, 0);
    } catch (Exception e) {
        e.printStackTrace();
    }
}
