private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("Invalid bucket label");
    }

    // Move all vertices from the bucket with label minLabel to bucket 0
    Set<Integer> minLabelBucket = bucketsByLabel.get(minLabel);
    for (Integer vertexLabel : minLabelBucket) {
        bucketsByLabel.get(0).add(vertexLabel);
    }

    // Clear the bucket with label minLabel
    bucketsByLabel.set(minLabel, new HashSet<>());

    // Update the labeling
    List<Integer> updatedLabels = new ArrayList<>(labels);
    updatedLabels.remove(minLabel);
    for (int i = minLabel; i < updatedLabels.size(); i++) {
        updatedLabels.set(i, i);
    }
}
