public void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Check if the bucket with label minLabel exists in bucketsByLabel
    if (bucketsByLabel.size() <= minLabel) {
        throw new IllegalArgumentException("Invalid bucket label: " + minLabel);
    }

    // Step 1: Move all vertices from the bucket with label minLabel to the bucket with label 0
    Set<Integer> bucketWithMinLabel = bucketsByLabel.get(minLabel);
    if (bucketWithMinLabel != null) {
        bucketWithMinLabel.addAll(bucketsByLabel.get(0));
        bucketsByLabel.remove(bucketWithMinLabel);
        bucketsByLabel.add(0, bucketWithMinLabel);
    }

    // Step 2: Clear the bucket with label minLabel
    bucketsByLabel.remove(minLabel);

    // Step 3: Update the labels of the vertices
    for (int i = 0; i < labels.size(); i++) {
        if (labels.get(i) == minLabel) {
            labels.set(i, 0);
        } else {
            labels.set(i, labels.get(i) - 1);
        }
    }
}
