import java.util.ArrayList;
import java.util.List;
import java.util.stream.LongStream;

class SuffixSumCalculator {
    public Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
        List<Integer> suffixSum = new ArrayList<>();
        long totalSum = 0;

        // Calculate prefix sum
        LongStream.range(0, bounds.size()).forEach(i -> {
            if (i > 0) {
                suffixSum.add(suffixSum.get(i - 1) + bounds.get(i));
            } else {
                suffixSum.add(bounds.get(i));
            }
            totalSum += bounds.get(i);
        });

        return new Pair<>(suffixSum, totalSum);
    }
}
