private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> subSums = new ArrayList<>();
    long total = 0;

    // Calculate the sum of all elements.
    for (int num : bounds) {
        total += num;
    }

    // Calculate the suffix sums.
    for (int num : bounds) {
        int currentSum = total - num;
        subSums.add(currentSum);
    }

    return new Pair<>(subSums, total);
}
