public synchronized void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list.isEmpty()) {
        return;
    }

    List<ListNode<E>> nodesToRemove = new ArrayList<>();
    List<ListNode<E>> nodesToMove = new ArrayList<>();

    // Traverse the original list and collect nodes to be removed and moved
    ListNode<E> current = list.head();
    while (current != null) {
        if (current.previousNode() != null && current.previousNode().data() == null) {
            nodesToRemove.add((ListNodeImpl<E>) current.previousNode().data());
            nodesToRemove.add(current.nextNode());
        }

        currentNode = current.nextNode();
    }

    // Adjust next pointers of nodes to be moved
    for (int i = nodesToMove.size() - 1; i >= 0; i--) {
        nodesToMove.get(i).setNext(nodesToMove.get(i + 1));
        nodesToMove.get(i + 1).setPrevious(nodesToMove.get(i));
    }

    // Insert nodes to be moved at the head of this list
    for (int i = 0; i < nodesToMove.size(); i++) {
        nodesToMove.get(i).setNext(head);
        head.setPrevious(nodesToMove.get(i));
        head = nodesToMove.get(i);
    }

    // Insert nodes to be removed at the head of this list
    for (int i = 0; i < nodesToRemove.size(); i++) {
        nodesToRemove.get(i).setNext(null); // Set the next pointer to null
        nodesToRemove.get(i).setPrevious(head);
        head.setPrevious(nodesToRemove.get(i));
        head = nodesToRemove.get(i);
        // Also add the node to a collection for removal
        items.add(nodesToRemove.get(i));
    }
}
