public static String base64Decode(final String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }

    int length = s.length();
    if (length % 4 != 0) {
        throw new IllegalArgumentException("Must be a multiple of 4");
    }

    StringBuilder decoded = new StringBuilder();
    for (int i = 0; i < length; i += 4) {
        String group = s.substring(i, i + 4);
        int first = hexCharToDigit(group.charAt(0));
        int second = hexCharToDigit(group.charAt(1));
        int third = hexCharToDigit(group.charAt(2));
        int fourth = hexCharToDigit(group.charAt(3));

        int decodedByte = ((first << 4) | second) * 16 + (third << 2) + fourth;
        decoded.append((char) decodedByte);
    }

    return decoded.toString();
}
