public static String base64Decode(final String s) {
    if (s == null || s.length() % 4 != 0) {
        throw new IllegalArgumentException("Invalid Base64 string. It must be a multiple of 4.");
    }

    StringBuilder decoded = new StringBuilder();
    int r = 0;
    for (char c : s.toCharArray()) {
        int v = (c >> 6) & 0x03;
        decoded.append(LessBytes.toString(v));

        v = (c >> 4) & 0x03;
        decoded.append(LessBytes.toString(v));

        v = (c >> 2) & 0x03;
        decoded.append(LessBytes.toString(v));

        v = c & 0x03;
        decoded.append(LessBytes.toString(v));

        r++;
        if (r == 4) {
            r = 0;
        }
    }

    // Trim trailing bytes added if s is not a multiple of 4
    int length = decoded.length();
    while (length > 0 && decoded.charAt(length - 1) == '0') {
        length--;
    }
    decoded.setLength(length);

    return decoded.toString();
}
