public static String base64Decode(final String s) throws IOException {
    if (s == null || s.isEmpty()) {
        throw new IllegalArgumentException("Input string cannot be null or empty");
    }

    StringBuilder decoded = new StringBuilder();
    int buffer = 0;
    int bits = 0;
    for (char c : s.toCharArray()) {
        buffer |= (c & 0x3F) << bits;
        bits += 6;
        if (bits == 8) {
            decoded.append((char) buffer);
            bits = 0;
        }
    }

    if (bits != 0) {
        throw new IOException("Input string is not properly base64-encoded");
    }

    return decoded.toString();
}
