private List<Pair<Integer, Integer>> calculateSeparator(DirectedEdge edge, DirectedEdge neighbor) {
    List<Pair<Integer, Integer>> separator = new ArrayList<>();

    for (DirectedEdge current : adj[edge.to]) {
        if (current != edge && current.to != neighbor.to && current != neighbor) {
            pair.add(new Pair<>(current.getTo(), current.getWeight()));
        }
    }

    for (DirectedEdge current : adj[neighbor.to]) {
        if (current != edge && current.to != neighbor) {
            pair.add(new Pair<>(current.getFrom(), current.getWeight()));
        }
    }

    Collections.sort(separator, new Comparator<Pair<Integer, Integer>>() {
        @Override
        public int compare(Pair<Integer, Integer> a, Pair<Integer, Integer> b) {
            return (a.getKey() - b.getKey());
        }
    });

    return separator;
}
