private static <V,E>boolean isClique(Graph<V,E> graph,Set<V> vertices){
    if(vertices == null || graph == null || vertices.isEmpty()) {
        throw new IllegalArgumentException("Vertices and graph cannot be null or empty");
    }

    Set<Set<V>> inducedSubgraph = induceSubgraph(graph, vertices);

    for(int i = 0; i < inducedSubgraph.size(); i++) {
        List<V> verticesSet = inducedSubgraph.get(i);
        if(verticesSet.size() < inducedSubgraph.size()) {  // If a subgraph consists of fewer vertices than itself, it is not a clique
            return false;
        }
        for(int j = 0; j < verticesSet.size(); j++) {
            if(j == i) continue;  // Skip comparing a vertex to itself
            for(int k = 0; k < verticesSet.size(); k++) {
                if(k == i || k == j) continue;  // Skip comparing a vertex to itself or a vertex it is already comparing to
                if(!graph.isEdge(verticesSet.get(i), verticesSet.get(j))) {
                    return false;
                }
            }
        }
    }

    return true;
}

private static <V,E>Set<Set<V>> induceSubgraph(Graph<V,E> graph, Set<V> vertices){
    Set<Set<V>> inducedSubgraph = new HashSet<>();
    for(V vertex: vertices){
        Set<V> inducedVertices = new HashSet<>();
        inducedVertices.add(vertex);
        List<E> edgesFromVertex = graph.outgoingEdgesOf(vertex);
        for(E edge: edgesFromVertex){
            V adjacentVertex = graph.getEdgeTarget(edge);
            if(inducedVertices.contains(adjacentVertex)){
                inducedVertices.add(vertex);
            }
        }
        inducedSubgraph.add(inducedVertices);
    }
    return inducedSubgraph;
}
