public class KeyBoundFinder {
    private Map<K, Integer> keyBounds = new HashMap<>();

    public List<Integer> computeLowerBounds(List<K> keys) {
        if (keys == null || keys.isEmpty()) {
            throw new IllegalArgumentException("Input list cannot be null or empty");
        }

        Map<K, List<Integer>> keyToLowerBounds = new HashMap<>();

        for (K key : keys) {
            List<Integer> lowerBounds = new LinkedList<>();
            keyToLowerBounds.put(key, lowerBounds);
            findLowerBounds(key, lowerBounds, 0);
        }

        List<Integer> result = new LinkedList<>();
        for (List<Integer> lowerBounds : keyToLowerBounds.values()) {
            for (Integer lowerBound : lowerBounds) {
                result.add(lowerBound);
            }
        }

        return result;
    }

    private void findLowerBounds(K key, List<Integer> lowerBounds, int currentDepth) {
        // Base case: reached the end of the tree
        if (currentDepth == key.size()) {
            lowerBounds.addkey.hashCode());
            return;
        }

        K childKey = key.charAt(currentDepth);
        Node<Integer> childNode = getChildNode(childKey, currentDepth, null);

        if (childNode != null) {
            findLowerBounds(childNode.key, lowerBounds, currentDepth + 1);
        } else {
            // Create a new leaf node and add it to the parent node
            Node<Integer> newNode = new Node<>(childKey, currentDepth);

            // Recursively find lower bounds for the child node
            findLowerBounds(newNode.key, lowerBounds, currentDepth + 1);

            // Add the current node to the parent node's children
            if (parent != null) {
                parent.children.put(childKey, newNode);
            }
        }
    }

    // Node class to represent a node in the tree
    private static class Node<K, T> {
        K key;
        int depth;
        List<Node<K, T>> children;

        public Node(K key, int depth) {
            this.key = key;
            this.depth = depth;
            this.children = new ArrayList<>();
        }
    }

    // Example usage of the KeyBoundFinder class
    public static void main(String[] args) {
        KeyBoundFinder finder = new KeyBoundFinder();
        List<Integer> result = finder.computeLowerBounds(List.of("abc", "abd", "ac", "ad", "ae", "af"));
        System.out.println(result);
    }
}
