private void pop(final String descriptor) {
    // Check if the descriptor is valid
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Invalid descriptor");
    }

    // Split the descriptor into its components
    final String[] parts = descriptor.split(" ");
    final int length = parts.length;
    int poppedTypes = 0;

    // Loop through the descriptor and pop the appropriate types
    for (int i = 0; i < length; i++) {
        final String part = parts[i];
        if (part.endsWith("[]")) {
            // Pop an array type
            poppedTypes++;
        } else if (part.endsWith(")")) {
            // Pop a method return type
            poppedTypes++;
        } else {
            // Pop a type argument
            poppedTypes++;
        }
    }

    // Pop the total number of types specified
    System.out.println("Popped " + poppedTypes + " types from the stack");
}
