public static String applyRelativePath(String path,String relativePath) throws NullPointerException, IllegalArgumentException, MalformedURLException {
    if (path == null || relativePath == null || path.isEmpty() || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Path and relative path cannot be null or empty");
    }

    // Trim and simplify the path and relative path strings
    path = path.trim().replaceAll("[ ]", "/");
    relativePath = relativePath.isEmpty() ? "/" : relativePath.trim().replaceAll("[ ]", "/");

    // Apply the relative path
    URI baseURI;
    try {
        baseURI = new URI(path);
    } catch (MalformedURLException e) {
        throw new IllegalArgumentException("Path is invalid", e);
    }

    URI relativeURI;
    try {
        relativeURI = new URI(relativePath);
    } catch (MalformedURLException e) {
        throw new IllegalArgumentException("Relative path is invalid", e);
    }

    URI combinedURI = baseURI.resolve(relativeURI);
    return combinedURI.toString();
}
